import { Component, inject, OnInit } from '@angular/core';
import { ItemSale } from 'src/app/shared/models/item-sale.model';
import { CartService } from 'src/app/shared/services/cart.service';

@Component({
  selector: 'app-cart',
  templateUrl: './cart.component.html',
  styleUrls: ['./cart.component.scss'],
})
export class CartComponent implements OnInit {
  private cartService = inject(CartService);
  products: ItemSale[] = [];
  total = 0;
  dropdownAberto = false;

  ngOnInit(): void {
    this.cartService.cart$.subscribe((products) => {
      this.products = products;
      this.total = this.cartService.getTotal();
    });
  }

  updateQuantity(produtoId: number, quantidade: number) {
    this.cartService.updateQuantity(produtoId, quantidade);
  }

  remove(produtoId: number) {
    this.cartService.remove(produtoId);
  }

  toggleDropdown() {
    this.dropdownAberto = !this.dropdownAberto;
  }
}
<div class="position-relative">
  <button class="btn btn-outline-primary" (click)="toggleDropdown()">
    <i class="bi bi-cart"></i> ({{ products.length }})
  </button>

  <div
    class="dropdown-menu show"
    *ngIf="dropdownAberto"
    style="width: 300px; right: 0; position: absolute"
  >
    <div class="p-3">
      <h5>Carrinho de Compras</h5>
      <hr />
      <div *ngIf="products.length === 0">Seu carrinho está vazio.</div>

      <div
        *ngFor="let product of products"
        class="d-flex justify-content-between align-items-center mb-2"
      >
        <div>
          <strong>{{ product.book?.title }}</strong>
          <br />
          <span>R$ {{ product.price | number : "1.2-2" }}</span>
        </div>

        <div class="d-flex align-items-center">
          <i
            class="bi bi-dash-circle"
            (click)="updateQuantity(product.id, product.quantity - 1)"
          ></i>
          <input
            type="number"
            [(ngModel)]="product.quantity"
            (change)="updateQuantity(product.id, product.quantity)"
            class="form-control form-control-sm mx-1 ms-2"
            style="width: 50px"
          />
          <i
            class="bi bi-plus-circle"
            (click)="updateQuantity(product.id, product.quantity + 1)"
          ></i>

          <i
            class="bi bi-trash text-danger ms-2"
            (click)="remove(product.id)"
          ></i>
        </div>
      </div>

      <hr />
      <strong>Total: R$ {{ total | number : "1.2-2" }}</strong>
      <hr *ngIf="products.length > 0" />
      <a
        class="btn btn-success w-100 mt-2"
        [routerLink]="['/checkout']"
        *ngIf="products.length > 0"
      >
        Finalizar Compra
      </a>
    </div>
  </div>
</div>

import { Component, OnInit, OnDestroy, inject } from '@angular/core';
import { FormControl } from '@angular/forms';
import { debounceTime, distinctUntilChanged, Subject, takeUntil } from 'rxjs';
import { Book } from 'src/app/shared/models/book.model';
import { Category } from 'src/app/shared/models/category.model';
import { ItemSale } from 'src/app/shared/models/item-sale.model';
import { PaginatedResponse } from 'src/app/shared/models/paginated-response.model';
import { BookService } from 'src/app/shared/services/book.service';
import { CartService } from 'src/app/shared/services/cart.service';
import { CategoryService } from 'src/app/shared/services/category.service';

@Component({
  selector: 'app-shop',
  templateUrl: './shop.component.html',
  styleUrls: ['./shop.component.scss'],
})
export class ShopComponent implements OnInit, OnDestroy {
  private cartService = inject(CartService);
  private categoryService = inject(CategoryService);
  private bookService = inject(BookService);
  private destroy$ = new Subject<void>();

  searchControl = new FormControl<string>('');
  categories: Category[] = [];
  books: Book[] = [];

  selectedCategories: number[] = [];
  currentPage = 0;
  pageSize = 6;
  totalItems = 0;
  totalPages = 0;

  ngOnInit(): void {
    this.observeSearchChange();
    this.loadCategories();
    this.loadBooks();
  }

  private observeSearchChange(): void {
    this.searchControl.valueChanges
      .pipe(debounceTime(500), distinctUntilChanged(), takeUntil(this.destroy$))
      .subscribe((value) => {
        this.currentPage = 0;
        this.loadBooks(value || '');
      });
  }

  private loadCategories(): void {
    this.categoryService.getAll().subscribe((res) => {
      this.categories = res.data;
    });
  }

  private loadBooks(filter: string = ''): void {
    if (this.selectedCategories.length > 0) {
      this.bookService
        .getAllByCategories(this.selectedCategories, filter)
        .subscribe((response) => this.fillList(response));
    } else {
      this.bookService
        .getAll(this.currentPage, filter, this.pageSize)
        .subscribe((response) => this.fillList(response));
    }
  }

  private fillList(response: PaginatedResponse<Book>): void {
    this.books = response.data;
    this.currentPage = response.pagination.currentPage;
    this.totalItems = response.pagination.totalItems;
    this.totalPages = response.pagination.totalPages;
  }

  filterBooks(category: Category, event: Event): void {
    const checked = (event.target as HTMLInputElement).checked;

    if (checked) {
      this.selectedCategories.push(category.id);
    } else {
      this.selectedCategories = this.selectedCategories.filter(
        (id) => id !== category.id
      );
    }

    this.currentPage = 0;
    this.loadBooks(this.searchControl.value || '');
  }

  goToPage(page: number): void {
    if (page >= 1 && page <= this.totalPages) {
      this.currentPage = page;
      this.loadBooks(this.searchControl.value || '');
    }
  }
  getAuthors(book: Book) {
    return book.author?.map((a) => a.name).join(', ');
  }

  addToCart(book: Book): void {
    const product: ItemSale = {
      id: 1,
      saleId: 1,
      bookId: book.id,
      quantity: 1,
      price: book.price,
      book,
    };

    this.cartService.add(product);
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }
}
<div class="d-flex justify-content-between">
  <h3>Loja</h3>
  <app-cart></app-cart>
</div>

<div class="row mb-3">
  <div class="input-group me-3">
    <span class="input-group-text"><i class="bi bi-search"></i></span>
    <input
      type="text"
      class="form-control"
      placeholder="Pesquisar..."
      [formControl]="searchControl"
      data-cy="input-search"
    />
  </div>
</div>
<div class="row">
  <div class="col-md-3">
    <div class="card">
      <div class="card-header">Categorias</div>
      <div class="card-body overflow-auto" style="max-height: 300px">
        <div *ngFor="let category of categories" class="form-check">
          <input
            class="form-check-input"
            type="checkbox"
            [value]="category.id"
            (change)="filterBooks(category, $event)"
          />
          <label class="form-check-label">{{ category.description }}</label>
        </div>
      </div>
    </div>
  </div>

  <div class="col-md-9">
    <div class="row">
      <div class="col-md-4 mb-4" *ngFor="let book of books">
        <div class="card">
          <div class="card-body">
            <h5 class="card-title">{{ book.title }}</h5>
            <p class="card-text">
              {{ getAuthors(book) }}
            </p>
            <p class="card-text">
              <strong>R$</strong> {{ book.price.toFixed(2) }}
            </p>
            <button
              class="btn btn-outline-primary w-100"
              (click)="addToCart(book)"
            >
              <i class="bi bi-cart-plus"></i>
            </button>
          </div>
        </div>
      </div>
    </div>
    <div class="d-flex justify-content-center align-items-center mb-3">
      <ngb-pagination
        [(page)]="currentPage"
        [pageSize]="pageSize"
        [collectionSize]="totalItems"
        (pageChange)="goToPage($event)"
      />
    </div>
  </div>
</div>

